//! The hardware estimates in `HARDWARE-CAPs.md` are generated by `scripts/capability-estimates.py`;
//! the committed tables must be that script's output, and the measured logs the docs cite must exist.

use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .unwrap()
        .to_path_buf()
}

/// The script's stdout, or `None` (with a printed reason) when `python3` is not installed.
fn script_output() -> Option<String> {
    let out = Command::new("python3")
        .args(["-I", "scripts/capability-estimates.py"])
        .current_dir(root())
        .output();
    match out {
        Ok(o) => {
            assert!(o.status.success(), "{}", String::from_utf8_lossy(&o.stderr));
            Some(String::from_utf8(o.stdout).unwrap())
        }
        Err(e) => {
            eprintln!("SKIP: python3 not available ({e})");
            None
        }
    }
}

#[test]
fn every_table_row_the_script_prints_is_in_hardware_caps() {
    let Some(text) = script_output() else { return };
    let doc = fs::read_to_string(root().join("HARDWARE-CAPs.md")).unwrap();
    let rows: Vec<&str> = text.lines().filter(|l| l.starts_with("| ")).collect();
    assert!(
        rows.len() > 40,
        "the script printed only {} rows",
        rows.len()
    );
    let missing: Vec<&&str> = rows.iter().filter(|r| !doc.contains(**r)).collect();
    assert!(
        missing.is_empty(),
        "stale rows in HARDWARE-CAPs.md: {missing:#?}"
    );
}

#[test]
fn the_script_states_its_assumptions_and_marks_the_hypothetical_rows() {
    let Some(text) = script_output() else { return };
    assert!(text.contains("ASSUMPTION"), "hypothetical rows must say so");
    assert!(text.contains("calibrated on one card"));
    assert!(
        text.contains("OOM (measured"),
        "the measured MX330 limit is shown"
    );
}

#[test]
fn the_logs_the_capability_doc_cites_are_committed() {
    let doc = fs::read_to_string(root().join("CAPABILITY.md")).unwrap();
    assert!(doc.contains("docs/logs/capability-2026-11-14-"));
    for f in [
        "capability-2026-11-14-MX330.txt",
        "capability-2026-11-14-Xe.txt",
        "capability-2026-11-14-MX330-llama-bench.txt",
        "capability-2026-11-14-Xe-llama-bench.txt",
    ] {
        let p = root().join("docs/logs").join(f);
        let text = fs::read_to_string(&p).unwrap_or_else(|e| panic!("{}: {e}", p.display()));
        assert!(text.contains("| "), "{f} has no table rows");
    }
}

#[test]
fn the_two_docs_and_the_readme_link_to_each_other() {
    let read = |f: &str| fs::read_to_string(root().join(f)).unwrap();
    assert!(read("CAPABILITY.md").contains("HARDWARE-CAPs.md"));
    assert!(read("HARDWARE-CAPs.md").contains("CAPABILITY.md"));
    let readme = read("README.md");
    assert!(readme.contains("CAPABILITY.md") && readme.contains("HARDWARE-CAPs.md"));
}
